import os
for root, ds, fs in os.walk('studies'):
 for f in fs: print(root, f)

import glob,gzip
for f in sorted(glob.glob('studies/data/raw/*matrix*')):
 print('\nFILE',f)
 for l in gzip.open(f,'rt'):
  if l.startswith('!Sample_') and not any(x in l for x in ['!Sample_data','!Sample_contact','!Sample_status','!Sample_submission','!Sample_last_update','!Sample_platform','!Sample_taxid','!Sample_organism']):print(l.strip())

import glob,gzip,csv
for f in sorted(glob.glob('studies/data/raw/*matrix*'))[2:]:
 print('\nFILE',f)
 rows=[r for r in csv.reader(gzip.open(f,'rt'),delimiter='\t') if r and r[0] in ['!Sample_title','!Sample_geo_accession','!Sample_source_name_ch1','!Sample_characteristics_ch1','!Sample_description','!Sample_treatment_protocol_ch1','!Sample_supplementary_file']]
 for i in range(1,len(rows[0])):
  print(' | '.join(r[0].replace('!Sample_','')+': '+r[i] for r in rows))
